import { DOMAIN_WBS_TEMPLATE_CATALOGS, type DomainWbsTemplateCatalog } from './domainWbsTemplateCatalogs.js'

type InternalFlowCategoryType =
  | 'division'
  | 'sub_division'
  | 'item_work'
  | 'process'
  | 'activity_step'

type InternalFlowRelationKind =
  | 'hard_sequence'
  | 'soft_sequence'
  | 'parallel_allowed'
  | 'acceptance_gate'

type InternalFlowCondition = {
  field:
    | 'project_type_code'
    | 'structure_type_code'
    | 'method_variant_code'
    | 'element_variant_code'
    | 'climate_signal'
    | 'monthly_climate_signal'
    | 'weather_impact_band'
    | 'predecessor_name'
    | 'successor_name'
  operator: 'includes_any' | 'excludes_any'
  values: string[]
}

type InternalFlowEvidenceRef = {
  code: string
  level: 'standard' | 'clause' | 'process' | 'enterprise_method' | 'execution_history'
  ref?: string
  rationale?: string
}

type InternalFlowConditionalEffect = {
  id: string
  when: InternalFlowCondition[]
  relationKind?: InternalFlowRelationKind
  dependencyType?: 'FS' | 'SS' | 'FF' | 'SF'
  lagDays?: number
  relationRole?: 'workflow' | 'inspection'
  strength?: 'hard' | 'recommended' | 'candidate'
  reasonCode?: string
  curationBasis?: string
  scheduleMode?: 'sequential' | 'parallel_with_previous'
  requiresAllPreviousSiblings?: boolean
  evidenceCodes?: string[]
  evidenceRefs?: InternalFlowEvidenceRef[]
}

type InternalFlowGeneralizationHint = {
  status: 'semantic_rule' | 'stable_code_backfill'
  targetPattern?: string
  promotionPriority?: 'P0' | 'P1' | 'P2'
  reason: string
}

type InternalFlowRuleSeed = {
  id: string
  matchMode?: 'exact' | 'suffix' | 'stable_code'
  predecessorStableCode?: string
  successorStableCode?: string
  applicableCategoryTypes?: InternalFlowCategoryType[]
  predecessorName: string
  successorName: string
  relationKind: InternalFlowRelationKind
  createsDependency: boolean
  dependencyType: 'FS' | 'SS' | 'FF' | 'SF'
  lagDays: number
  relationRole: 'workflow' | 'inspection'
  strength: 'hard' | 'recommended' | 'candidate'
  reasonCode: string
  curationBasis: string
  scheduleMode?: 'sequential' | 'parallel_with_previous'
  requiresAllPreviousSiblings?: boolean
  evidenceCodes?: string[]
  evidenceRefs?: InternalFlowEvidenceRef[]
  governancePriority?: 'P0' | 'P1' | 'P2'
  applicableWhen?: InternalFlowCondition[]
  conditionalEffects?: InternalFlowConditionalEffect[]
  generalizationHint?: InternalFlowGeneralizationHint
  additionalPredecessorStableCodes?: string[]
}

function flowRule(
  id: string,
  predecessorName: string,
  successorName: string,
  options: {
    kind: InternalFlowRelationKind
    dependencyType?: InternalFlowRuleSeed['dependencyType']
    lagDays?: number
    relationRole?: InternalFlowRuleSeed['relationRole']
    strength?: InternalFlowRuleSeed['strength']
    reasonCode?: string
    curationBasis: string
    matchMode?: InternalFlowRuleSeed['matchMode']
    scheduleMode?: InternalFlowRuleSeed['scheduleMode']
    requiresAllPreviousSiblings?: boolean
    applicableCategoryTypes?: InternalFlowCategoryType[]
    evidenceCodes?: string[]
    evidenceRefs?: InternalFlowEvidenceRef[]
    governancePriority?: InternalFlowRuleSeed['governancePriority']
    applicableWhen?: InternalFlowCondition[]
    conditionalEffects?: InternalFlowConditionalEffect[]
    generalizationHint?: InternalFlowGeneralizationHint
    additionalPredecessorStableCodes?: string[]
  },
): InternalFlowRuleSeed {
  const relationKind = options.kind
  const createsDependency = relationKind === 'hard_sequence' || relationKind === 'acceptance_gate'
  const relationRole = options.relationRole ?? (relationKind === 'acceptance_gate' ? 'inspection' : 'workflow')
  const evidenceCodes = options.evidenceCodes ?? inferInternalFlowFallbackEvidenceCodes(predecessorName, successorName, relationKind)
  return {
    id,
    matchMode: options.matchMode ?? 'suffix',
    predecessorName,
    successorName,
    relationKind,
    createsDependency,
    dependencyType: options.dependencyType ?? (createsDependency ? 'FS' : 'SS'),
    lagDays: options.lagDays ?? 0,
    relationRole,
    strength: options.strength ?? (createsDependency ? 'recommended' : 'candidate'),
    reasonCode: options.reasonCode ?? (
      relationKind === 'acceptance_gate'
        ? 'QUALITY_GATE_REQUIRES_PRIOR_WORK'
        : relationKind === 'parallel_allowed'
          ? 'PREPARATION_CAN_OVERLAP'
          : relationKind === 'soft_sequence'
            ? 'ORDER_IS_GUIDANCE_NOT_BLOCKING'
            : 'PHYSICAL_SEQUENCE_REQUIRES_HANDOFF'
    ),
    curationBasis: options.curationBasis,
    scheduleMode: options.scheduleMode,
    requiresAllPreviousSiblings: options.requiresAllPreviousSiblings,
    applicableCategoryTypes: options.applicableCategoryTypes,
    evidenceCodes,
    evidenceRefs: options.evidenceRefs,
    governancePriority: options.governancePriority ?? 'P2',
    applicableWhen: options.applicableWhen,
    conditionalEffects: options.conditionalEffects,
    generalizationHint: options.generalizationHint,
    additionalPredecessorStableCodes: options.additionalPredecessorStableCodes,
  }
}

function stableCodeFlowRule(
  predecessorStableCode: string,
  predecessorName: string,
  successorStableCode: string,
  successorName: string,
  options: Parameters<typeof flowRule>[3],
): InternalFlowRuleSeed {
  return {
    ...flowRule(`stable-code-${predecessorStableCode}-to-${successorStableCode}`, predecessorName, successorName, options),
    matchMode: 'stable_code',
    predecessorStableCode,
    successorStableCode,
  }
}

type StableCodeBackfillItem = readonly [
  predecessorStableCode: string,
  predecessorName: string,
  successorStableCode: string,
  successorName: string,
  relationKind?: InternalFlowRelationKind,
  overrides?: Partial<Parameters<typeof flowRule>[3]>,
]

function makeStableCodeBackfillItem(
  predecessorStableCode: string,
  predecessorName: string,
  successorStableCode: string,
  successorName: string,
  relationKind: InternalFlowRelationKind,
  overrides?: Partial<Parameters<typeof flowRule>[3]>,
): StableCodeBackfillItem {
  if (overrides) {
    return [predecessorStableCode, predecessorName, successorStableCode, successorName, relationKind, overrides]
  }
  return [predecessorStableCode, predecessorName, successorStableCode, successorName, relationKind]
}

function l2ActivityStepEvidenceRefs(codes: readonly string[], rationale: string): InternalFlowEvidenceRef[] {
  return codes.map((code) => ({
    code,
    level: 'process',
    rationale,
  }))
}

function flattenDomainWbsNodes(catalog: DomainWbsTemplateCatalog) {
  const visit = (node: DomainWbsTemplateCatalog['divisions'][number]): DomainWbsTemplateCatalog['divisions'][number][] => [
    node,
    ...(node.children ?? []).flatMap(visit),
  ]
  return catalog.divisions.flatMap(visit)
}

function domainWbsNode(templateId: string, stableCode: string) {
  const catalog = DOMAIN_WBS_TEMPLATE_CATALOGS.find((candidate) => candidate.templateId === templateId)
  return catalog ? flattenDomainWbsNodes(catalog).find((candidate) => candidate.stableCode === stableCode) : undefined
}

function domainWbsNodeName(
  templateId: string,
  stableCode: string,
  allowedCategoryTypes: readonly InternalFlowCategoryType[],
) {
  const node = domainWbsNode(templateId, stableCode)
  if (!node) {
    throw new Error(`Missing domain WBS node ${templateId}:${stableCode} for stable-code backfill`)
  }
  if (!allowedCategoryTypes.includes(node.categoryType)) {
    throw new Error(
      `Missing domain WBS ${allowedCategoryTypes.join('/')} ${templateId}:${stableCode} for stable-code backfill`,
    )
  }
  return node.name
}

function domainWbsProcessName(templateId: string, stableCode: string) {
  const node = domainWbsNode(templateId, stableCode)
  if (!node || node.categoryType !== 'process') {
    throw new Error(`Missing domain WBS process ${templateId}:${stableCode} for stable-code backfill`)
  }
  return node.name
}

