function domainCatalogSequentialProcessBackfillItems(templateId: string): StableCodeBackfillItem[] {
  const catalog = DOMAIN_WBS_TEMPLATE_CATALOGS.find((candidate) => candidate.templateId === templateId)
  if (!catalog) throw new Error(`Missing domain WBS catalog ${templateId} for sequential process backfill`)

  return flattenDomainWbsNodes(catalog)
    .filter((node) => node.categoryType === 'item_work')
    .flatMap((itemPack) => {
      const processes = (itemPack.children ?? []).filter((node) => node.categoryType === 'process')
      return processes.slice(1).map((successor, index) => {
        const predecessor = processes[index]!
        const isFinalGate = index === processes.length - 2
        return makeStableCodeBackfillItem(
          predecessor.stableCode,
          predecessor.name,
          successor.stableCode,
          successor.name,
          isFinalGate ? 'acceptance_gate' : 'hard_sequence',
          {
            applicableCategoryTypes: ['process'],
            strength: 'hard',
            governancePriority: 'P1',
            evidenceCodes: catalog.sourceStandards,
            curationBasis: `Curated L2 process sequence for ${templateId}:${itemPack.stableCode}; the catalog order represents the executable same-pack field handoff and the final edge closes the pack acceptance gate.`,
            generalizationHint: {
              status: 'stable_code_backfill',
              targetPattern: `${predecessor.name} -> ${successor.name}`,
              promotionPriority: 'P1',
              reason: 'Keep this specialty sequence exact until completed-project replay supports a reusable semantic generalization.',
            },
          },
        )
      })
    })
}

