function stableCodeBackfillRules(items: readonly StableCodeBackfillItem[]): InternalFlowRuleSeed[] {
  return items.map((item, index) => {
    if (!Array.isArray(item)) {
      throw new TypeError(`stableCodeBackfillRules item #${index + 1} must be a tuple: ${JSON.stringify(item)}`)
    }
    const [predecessorStableCode, predecessorName, successorStableCode, successorName, explicitKind, overrides] = item
    const allowedCategoryTypes = overrides?.applicableCategoryTypes ?? ['process']
    const resolvedPredecessorName = stableCodeBackfillNodeName(predecessorStableCode, predecessorName, allowedCategoryTypes)
    const resolvedSuccessorName = stableCodeBackfillNodeName(successorStableCode, successorName, allowedCategoryTypes)
    const kind = explicitKind ?? inferStableCodeBackfillKind(resolvedPredecessorName, resolvedSuccessorName)
    const { evidenceCodes: overrideEvidenceCodes, ...flowOverrides } = overrides ?? {}
    const evidenceCodes = overrideEvidenceCodes ?? inferStableCodeEvidenceCodes(predecessorStableCode, successorStableCode)
    return stableCodeFlowRule(predecessorStableCode, resolvedPredecessorName, successorStableCode, resolvedSuccessorName, {
      kind,
      scheduleMode: kind === 'parallel_allowed' ? 'parallel_with_previous' : undefined,
      curationBasis: kind === 'parallel_allowed'
        ? '该长尾同父级关系已纳入人工治理：允许按现场条件穿插推进，关键节点前统一闭合，并由真实执行数据继续反校验。'
        : kind === 'soft_sequence'
          ? '该长尾同父级关系已纳入人工治理：保留推荐顺序，不生成硬依赖，并由真实执行数据继续反校验。'
          : '该长尾同父级关系已纳入人工治理：按当前标准目录顺序生成同父级执行约束，并由真实执行数据继续反校验。',
      evidenceRefs: inferStableCodeEvidenceCodes(predecessorStableCode, successorStableCode).map((code) => ({
        code,
        level: 'standard',
        rationale: '当前为标准编号级证据；后续按高频关系补充条文级、工艺级或企业工法依据。',
      })),
      governancePriority: 'P2',
      generalizationHint: {
        status: 'stable_code_backfill',
        targetPattern: `${resolvedPredecessorName} -> ${resolvedSuccessorName}`,
        promotionPriority: 'P2',
        reason: '当前是 stable_code 精确回填，用于清零已知目录缺口；达到高频阈值后应反推为可复用语义规则。',
      },
      ...flowOverrides,
      evidenceCodes,
    })
  })
}

function activityStepStableCodeBackfillRules(items: readonly StableCodeBackfillItem[]): InternalFlowRuleSeed[] {
  for (const [predecessorStableCode, , successorStableCode, , , overrides] of items) {
    const allowedCategoryTypes = overrides?.applicableCategoryTypes ?? []
    if (allowedCategoryTypes.length !== 1 || allowedCategoryTypes[0] !== 'activity_step') {
      throw new TypeError(
        `activity-step L2 backfill must only target activity_step nodes: ${predecessorStableCode}->${successorStableCode}`,
      )
    }
  }
  return stableCodeBackfillRules(items)
}

function stableCodeBackfillItemsForSingleCategory(
  items: readonly StableCodeBackfillItem[],
  categoryType: InternalFlowCategoryType,
): StableCodeBackfillItem[] {
  return items.filter((item) => {
    const allowedCategoryTypes = item[5]?.applicableCategoryTypes ?? []
    return allowedCategoryTypes.length === 1 && allowedCategoryTypes[0] === categoryType
  })
}

const BUILDING_SCOPE_CRITICAL_CONTROL_REVIEW_EVIDENCE_CODES_BY_PREFIX: Record<string, string[]> = {
  DTC: ['GB50174', 'GB50339', 'GB50300'],
  FND: ['GB50202', 'GB50300'],
  IBU: ['GB50210', 'GB50300'],
  IKU: ['GB50210', 'GB50300'],
  MEP: ['GB50242', 'GB50243', 'GB50303', 'GB50300'],
  MIC: ['JGJ1', 'GB/T51231', 'GB50300'],
  UHR: ['GB50204', 'JGJ3', 'GB50300'],
}

function stableCodeAlphaPrefix(stableCode: string) {
  return stableCode.match(/^[A-Z]+/)?.[0] ?? ''
}

function buildingScopeCriticalControlReviewEvidenceRefs(prefix: string): InternalFlowEvidenceRef[] {
  const evidenceCodes = BUILDING_SCOPE_CRITICAL_CONTROL_REVIEW_EVIDENCE_CODES_BY_PREFIX[prefix] ?? ['GB50300']
  return evidenceCodes.map((code) => ({
    code,
    level: 'process',
    rationale: `${code} supports the same-parent / same-itemPack L2 critical control quality gate after process implementation records; this stable-code backfill does not own L5 wait/test-age or duration logic outside L2.`,
  }))
}

function buildingScopeCriticalControlReviewBackfillItems(): StableCodeBackfillItem[] {
  const items: StableCodeBackfillItem[] = []
  const allowedPrefixes = new Set(Object.keys(BUILDING_SCOPE_CRITICAL_CONTROL_REVIEW_EVIDENCE_CODES_BY_PREFIX))

  for (const catalog of DOMAIN_WBS_TEMPLATE_CATALOGS) {
    for (const node of flattenDomainWbsNodes(catalog)) {
      const children = node.children ?? []
      for (let index = 0; index < children.length - 1; index += 1) {
        const predecessor = children[index]
        const successor = children[index + 1]
        if (
          predecessor.categoryType !== 'activity_step'
          || successor.categoryType !== 'activity_step'
          || !predecessor.name.endsWith('过程实施记录')
          || !successor.name.endsWith('关键控制点复查')
        ) {
          continue
        }

        const prefix = stableCodeAlphaPrefix(predecessor.stableCode)
        if (!allowedPrefixes.has(prefix)) continue
        const evidenceCodes = BUILDING_SCOPE_CRITICAL_CONTROL_REVIEW_EVIDENCE_CODES_BY_PREFIX[prefix]
        items.push([
          predecessor.stableCode,
          predecessor.name,
          successor.stableCode,
          successor.name,
          'acceptance_gate',
          {
            applicableCategoryTypes: ['activity_step'],
            curationBasis: '建筑工程同一 itemPack 内过程实施记录完成后，关键控制点复查作为 L2 内部质量门闭合；该 stable-code 精确回填不跨包、不替代 L3/L4 放行，也不拥有 L5 等待、检测龄期或持续时间参数。',
            evidenceCodes,
            evidenceRefs: buildingScopeCriticalControlReviewEvidenceRefs(prefix),
            governancePriority: 'P2',
          },
        ])
      }
    }
  }

  return items
}

const BUILDING_SCOPE_CRITICAL_CONTROL_REVIEW_BACKFILL_ITEMS = buildingScopeCriticalControlReviewBackfillItems()

function hotelRemainingDepthGateItems(items: readonly HotelRemainingGateSeed[]): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const [itemCode, handoffName, firstFieldWorkName, middleFieldWorkName, finalFieldWorkName, handoffProcessIndex = 5] of items) {
    const handoffCode = `${itemCode}-P${String(handoffProcessIndex).padStart(2, '0')}`
    const firstFieldWorkCode = `${itemCode}-P${String(handoffProcessIndex + 1).padStart(2, '0')}`
    const middleFieldWorkCode = `${itemCode}-P${String(handoffProcessIndex + 2).padStart(2, '0')}`
    const finalFieldWorkCode = `${itemCode}-P${String(handoffProcessIndex + 3).padStart(2, '0')}`
    result.push(
      [handoffCode, handoffName, firstFieldWorkCode, firstFieldWorkName, 'acceptance_gate'],
      [firstFieldWorkCode, firstFieldWorkName, middleFieldWorkCode, middleFieldWorkName, 'hard_sequence'],
      [middleFieldWorkCode, middleFieldWorkName, finalFieldWorkCode, finalFieldWorkName, 'hard_sequence'],
      [firstFieldWorkCode, firstFieldWorkName, finalFieldWorkCode, finalFieldWorkName, 'acceptance_gate'],
    )
  }
  return result
}

function foundationRemainingDepthGateItems(items: readonly FoundationRemainingGateSeed[]): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const [itemCode, initialControlName, enablingWorkName, firstFieldWorkName] of items) {
    result.push(
      [`${itemCode}-P01`, initialControlName, `${itemCode}-P02`, enablingWorkName, 'acceptance_gate'],
      [`${itemCode}-P02`, enablingWorkName, `${itemCode}-P03`, firstFieldWorkName, 'acceptance_gate'],
    )
  }
  return result
}

function campusPromotedDepthGateItems(items: readonly CampusPromotedDepthGateSeed[]): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const [itemCode, baselineGatePredecessorName, baselineGateName, middleDepthWorkName, finalDepthCloseoutName] of items) {
    result.push(
      [`${itemCode}-P07`, middleDepthWorkName, `${itemCode}-P08`, finalDepthCloseoutName, 'acceptance_gate'],
      [`${itemCode}-P08`, finalDepthCloseoutName, `${itemCode}-P09`, baselineGateName, 'acceptance_gate'],
    )
  }
  return result
}

function renovationPromotedDepthGateItems(
  itemCodes: readonly string[],
  existingGateKeys: ReadonlySet<string> = new Set(),
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const itemCode of itemCodes) {
    const baselineGate: StableCodeBackfillItem = [`${itemCode}-P05`, 'renovation promoted baseline quality checkpoint', `${itemCode}-P06`, 'renovation promoted baseline handover or first depth work', 'acceptance_gate']
    const closeoutGate: StableCodeBackfillItem = [`${itemCode}-P08`, 'renovation promoted retest and rectification work', `${itemCode}-P09`, 'renovation promoted closeout and handover work', 'acceptance_gate']
    for (const gate of [baselineGate, closeoutGate]) {
      if (!existingGateKeys.has(`${gate[0]}->${gate[2]}`)) result.push(gate)
    }
  }
  return result
}

function cleanroomMedicalCriticalLongChainBackfillItems(
  items: readonly { itemCode: string; processCount: number; skipPairs?: readonly string[] }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  const defaultAcceptancePairIndexes = new Set([2, 7])
  for (const { itemCode, processCount, skipPairs = [] } of items) {
    const skippedPairs = new Set(skipPairs)
    for (let index = 1; index < processCount; index += 1) {
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      if (skippedPairs.has(`${predecessorStableCode}->${successorStableCode}`)) continue

      result.push(cleanroomMedicalBackfillItem(
        predecessorStableCode,
        successorStableCode,
        index + 1 === processCount || defaultAcceptancePairIndexes.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ))
    }
  }
  return result
}

