function industrialCleanroomCriticalLongChainBackfillItems(
  items: readonly { itemCode: string; processCount: number; skipPairs?: readonly string[] }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  const defaultAcceptancePairIndexes = new Set([2, 6])
  for (const { itemCode, processCount, skipPairs = [] } of items) {
    const skippedPairs = new Set(skipPairs)
    for (let index = 1; index < processCount; index += 1) {
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      if (skippedPairs.has(`${predecessorStableCode}->${successorStableCode}`)) continue

      result.push(industrialCleanroomBackfillItem(
        predecessorStableCode,
        successorStableCode,
        index + 1 === processCount || defaultAcceptancePairIndexes.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ))
    }
  }
  return result
}

