function buildingFineDetailCriticalLongChainBackfillItems(
  items: readonly { itemCode: string; processCount: number; acceptanceBreakIndexes?: readonly number[] }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const { itemCode, processCount, acceptanceBreakIndexes = [] } of items) {
    const acceptanceBreaks = new Set(acceptanceBreakIndexes)
    for (let index = 1; index < processCount; index += 1) {
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      result.push(buildingFineDetailBackfillItem(
        predecessorStableCode,
        successorStableCode,
        index + 1 === processCount || acceptanceBreaks.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ))
    }
  }
  return result
}

