function intelligentDepthGateItems(items: readonly IntelligentDepthGateSeed[]): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const item of items) {
    const itemCode = typeof item === 'string' ? item : item[0]
    const readinessName = typeof item === 'string'
      ? `${itemCode} INT cabling equipment platform or interface readiness checkpoint`
      : item[1]
    const functionalTestName = typeof item === 'string'
      ? `${itemCode} INT link functional security or integration test checkpoint`
      : item[2]
    const correctionRetestOrScenarioName = typeof item === 'string'
      ? `${itemCode} INT correction retest commissioning or scenario validation checkpoint`
      : item[3]
    const handoverName = typeof item === 'string'
      ? `${itemCode} INT handover record asset or operation-release checkpoint`
      : item[4]
    result.push(
      [`${itemCode}-P02`, readinessName, `${itemCode}-P05`, functionalTestName, 'acceptance_gate'],
      [`${itemCode}-P06`, correctionRetestOrScenarioName, `${itemCode}-P08`, handoverName, 'acceptance_gate'],
    )
  }
  return result
}

