function mepCoordinationLongChainBackfillItems(
  items: readonly { itemCode: string; processCount: number }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  const acceptancePairIndexes = new Set([2, 5, 8, 12])
  for (const { itemCode, processCount } of items) {
    for (let index = 1; index < processCount; index += 1) {
      result.push([
        `${itemCode}-P${String(index).padStart(2, '0')}`,
        `${itemCode} MEP coordination process P${String(index).padStart(2, '0')}`,
        `${itemCode}-P${String(index + 1).padStart(2, '0')}`,
        `${itemCode} MEP coordination process P${String(index + 1).padStart(2, '0')}`,
        index + 1 === processCount || acceptancePairIndexes.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ])
    }
  }
  return result
}

