function scheduleTrustLongChainBackfillItems(
  items: readonly {
    templateId: string
    itemCode: string
    processCount: number
    acceptanceBreakIndexes?: readonly number[]
    skipPairIndexes?: readonly number[]
  }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const { templateId, itemCode, processCount, acceptanceBreakIndexes = [], skipPairIndexes = [] } of items) {
    const acceptanceBreaks = new Set(acceptanceBreakIndexes)
    const skippedPairs = new Set(skipPairIndexes)
    for (let index = 1; index < processCount; index += 1) {
      if (skippedPairs.has(index)) continue
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      result.push([
        predecessorStableCode,
        domainWbsProcessName(templateId, predecessorStableCode),
        successorStableCode,
        domainWbsProcessName(templateId, successorStableCode),
        index + 1 === processCount || acceptanceBreaks.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ])
    }
  }
  return result
}

