function prefabricatedCriticalLongChainBackfillItems(
  items: readonly { itemCode: string; processCount: number; skipPairs?: readonly string[]; acceptanceBreakIndexes?: readonly number[] }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const { itemCode, processCount, skipPairs = [], acceptanceBreakIndexes = [] } of items) {
    const skippedPairs = new Set(skipPairs)
    const acceptanceBreaks = new Set(acceptanceBreakIndexes)
    for (let index = 1; index < processCount; index += 1) {
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      if (skippedPairs.has(`${predecessorStableCode}->${successorStableCode}`)) continue

      result.push([
        predecessorStableCode,
        `${itemCode} prefab critical long-chain process P${String(index).padStart(2, '0')}`,
        successorStableCode,
        `${itemCode} prefab critical long-chain process P${String(index + 1).padStart(2, '0')}`,
        index + 1 === processCount || acceptanceBreaks.has(index) ? 'acceptance_gate' : 'hard_sequence',
      ])
    }
  }
  return result
}

