function expandedProcessSeedInternalOrderBackfillItem(
  predecessorStableCode: string,
  successorStableCode: string,
  evidenceCodes: readonly string[],
  rationale: string,
  curationBasis: string,
): StableCodeBackfillItem {
  return [
    predecessorStableCode,
    `${predecessorStableCode} expanded process-seed internal predecessor`,
    successorStableCode,
    `${successorStableCode} expanded process-seed internal successor`,
    'hard_sequence',
    {
      applicableCategoryTypes: ['process'],
      evidenceCodes: [...evidenceCodes],
      evidenceRefs: l2ActivityStepEvidenceRefs(evidenceCodes, rationale),
      curationBasis,
    },
  ]
}

