function standardCatalogAdjacentBackfillItems(
  items: readonly {
    itemCode: string
    processCount: number
    acceptanceBreakIndexes?: readonly number[]
    skipPairs?: readonly string[]
    overridesByPair?: Record<string, Partial<Parameters<typeof flowRule>[3]>>
  }[],
): StableCodeBackfillItem[] {
  const result: StableCodeBackfillItem[] = []
  for (const { itemCode, processCount, acceptanceBreakIndexes = [], skipPairs = [], overridesByPair = {} } of items) {
    const acceptanceBreaks = new Set(acceptanceBreakIndexes)
    const skippedPairs = new Set(skipPairs)
    for (let index = 1; index < processCount; index += 1) {
      const predecessorStableCode = `${itemCode}-P${String(index).padStart(2, '0')}`
      const successorStableCode = `${itemCode}-P${String(index + 1).padStart(2, '0')}`
      if (skippedPairs.has(`${predecessorStableCode}->${successorStableCode}`)) continue
      const relationKind: InternalFlowRelationKind = index + 1 === processCount || acceptanceBreaks.has(index)
        ? 'acceptance_gate'
        : 'hard_sequence'
      const override = overridesByPair[`${predecessorStableCode}->${successorStableCode}`]

      const item = makeStableCodeBackfillItem(
        predecessorStableCode,
        `${itemCode} standard process P${String(index).padStart(2, '0')}`,
        successorStableCode,
        `${itemCode} standard process P${String(index + 1).padStart(2, '0')}`,
        relationKind,
        override,
      )
      result.push(item)
    }
  }
  return result
}

